750	// ===== 예산·원장 =====
751	
752	function budgetExceeded(task: PersistentTask): string | null {
753	  const { budget, checkpoint } = task
754	  if (checkpoint.stepsUsed >= budget.maxSteps) {
755	    return `단계 예산(${budget.maxSteps}단계)을 모두 사용했습니다.`
756	  }
757	  if (elapsedOf(task) >= budget.maxDurationMs) {
758	    return `실행 시간 예산(${Math.round(budget.maxDurationMs / 60_000)}분)을 모두 사용했습니다.`
759	  }
760	  // llmCalls 는 `usage` 이벤트를 센 값이다. agent.ts 는 **모델을 실제로 부른 모든 경로**에서
761	  // usage 를 내보내므로(토큰을 못 받는 tool-use 경로도 `{type:'usage', step}` 만이라도 보낸다)
762	  // 제공자와 무관하게 이 검사가 발동한다. 토큰 합계는 제공자가 알려줄 때만 누적된다 —
763	  // 세지 못한 토큰을 0으로 채워 사용량 표시를 거짓으로 만들지 않는다.
764	  if (task.usage.llmCalls >= budget.maxLlmCalls) {
765	    return `모델 호출 예산(${budget.maxLlmCalls}회)을 모두 사용했습니다.`
766	  }
767	  return null
768	}
769	
770	/**
771	 * 발행성 동작을 원장에 남긴다. 목적은 "정확히 한 번" 보장이 아니라 **모르는 채로 또 누르지 않기**다.
772	 * 완료 근거를 못 본 채 다음 구간을 시작하면 같은 글을 두 번 올릴 수 있다 → 구간 시작 전에 막는다.
773	 */
774	function recordExternalWrite(task: PersistentTask, label: string): void {
775	  const trimmed = label.trim().slice(0, 120)
776	  if (!trimmed) return
777	  task.externalWrites.push({ label: trimmed, at: Date.now(), confirmed: false })
778	  if (task.externalWrites.length > MAX_EXTERNAL_WRITES) {
779	    task.externalWrites.splice(0, task.externalWrites.length - MAX_EXTERNAL_WRITES)
780	  }
781	  task.updatedAt = Date.now()
782	  markDirty(task)
783	}
784	
785	/** 결과 파일 누적(중복 제거). 보고서·다운로드 경로는 완료 근거로도 쓰인다. */
786	function addResultFiles(task: PersistentTask, paths: string[]): void {
787	  let changed = false
788	  for (const p of paths) {
789	    if (!p || task.resultFiles.includes(p)) continue
790	    task.resultFiles.push(p)
791	    changed = true
792	  }
793	  if (changed) {
794	    if (task.resultFiles.length > 100) task.resultFiles.splice(0, task.resultFiles.length - 100)
795	    task.updatedAt = Date.now()
796	    markDirty(task)
797	  }
798	}
799	
800	function pendingExternalWrite(task: PersistentTask): { label: string; at: number; confirmed: boolean } | null {
801	  for (let i = task.externalWrites.length - 1; i >= 0; i--) {
802	    const w = task.externalWrites[i]
803	    if (w && !w.confirmed) return w
804	  }
805	  return null
806	}
807	
808	function confirmExternalWrites(task: PersistentTask): void {
809	  let changed = false
810	  for (const w of task.externalWrites) {
811	    if (!w.confirmed) { w.confirmed = true; changed = true }
812	  }
813	  if (changed) { task.updatedAt = Date.now(); markDirty(task) }
814	}
815	
816	// ===== 오류 분류 =====
817	
818	/**
819	 * 오류 문구로 원인을 나눈다. 문구는 `agent.ts` 의 `friendlyError` 와 `providers.ts` 가 실제로 내보내는
820	 * 것에 맞춘다 — 여기서 추측한 문구로 맞추면 분기가 전부 unknown 으로 떨어져 정책이 죽는다.
821	 */
822	export function classifyRetry(message: string): RetryKind {
823	  const m = str(message).toLowerCase()
824	  if (!m) return 'unknown'
825	  // 한도 초과는 네트워크 오류보다 먼저 본다(둘 다 "잠시 후 다시" 류 문구를 갖는다).
826	  if (/429|한도 초과|rate ?limit|too many requests|quota/.test(m)) return 'rate-limit'
