253	async function cleanupCard(session, marker) {
254	  let card = await evaluate(session, cardExpr(marker))
255	  let openedList = false
256	  if (!card) {
257	    // 완료·실패·중단(terminal) 카드는 인라인 진행 목록에서 빠지고 "📌 작업" 전체 목록에만 남는다
258	    // (의도된 동작 — livePtasks 필터). 거기서 찾아 정리한다.
259	    await openTaskList(session)
260	    openedList = true
261	    card = await evaluate(session, cardExpr(marker))
262	  }
263	  if (!card) { if (openedList) await closeTaskList(session); return }
264	  if (card.buttons.some((b) => b.includes('중단'))) {
265	    await clickCardButton(session, marker, '중단')
266	    await sleep(500)
267	  }
268	  await clickCardButton(session, marker, '목록에서 삭제')
269	  await sleep(300)
270	  if (openedList) await closeTaskList(session)
271	}
