  console.log('[2회차] 손상본 파일 =', fs.readdirSync(root).filter(f=>f.includes('corrupt')))
} else {
  E.engageQuotaRecord(g, 'comment'); E.engageQuotaRecord(g, 'comment'); E.engageQuotaRecord(g, 'comment')
